function fewestStops(target: number, startFuel: number, stations: number[][]): number {
  const n = stations.length;
  const best = new Array<number>(n + 1).fill(0);
  best[0] = startFuel;
  for (let i = 0; i < n; i++) {
    const [pos, fuel] = stations[i];
    for (let t = i; t >= 0; t--) {
      if (best[t] >= pos) best[t + 1] = Math.max(best[t + 1], best[t] + fuel);
    }
  }
  for (let t = 0; t <= n; t++) if (best[t] >= target) return t;
  return -1;
}

