class Solution:
    def fewestStops(self, target: int, startFuel: int, stations: List[List[int]]) -> int:
        n = len(stations)
        best = [startFuel] + [0] * n
        for i, (pos, fuel) in enumerate(stations):
            for t in range(i, -1, -1):
                if best[t] >= pos:
                    best[t + 1] = max(best[t + 1], best[t] + fuel)
        for t, far in enumerate(best):
            if far >= target:
                return t
        return -1

