function fewestStops(target: number, startFuel: number, stations: number[][]): number {
  const heap: number[] = []; // max-heap of litres
  const push = (v: number) => {
    heap.push(v);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[p] >= heap[i]) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  };
  const pop = (): number => {
    const top = heap[0], last = heap.pop()!;
    if (heap.length) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < heap.length && heap[l] > heap[m]) m = l;
        if (r < heap.length && heap[r] > heap[m]) m = r;
        if (m === i) break;
        [heap[m], heap[i]] = [heap[i], heap[m]];
        i = m;
      }
    }
    return top;
  };
  let reach = startFuel, stops = 0;
  for (const [pos, fuel] of [...stations, [target, 0]]) {
    while (reach < pos) {
      if (!heap.length) return -1;
      reach += pop();
      stops++;
    }
    push(fuel);
  }
  return stops;
}

